  // UNSAFE: inherited from Object prototype
  // e.g constructor
  if (hasOwnProperty(Object.prototype, method)) {
    return false;
  }
  // UNSAFE: inherited from Function prototype
  // e.g call, apply
  if (hasOwnProperty(Function.prototype, method)) {
    return false;
  }
  return true;
